const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define regions around Mount Isa and Townsville
  const mountIsa = ee.Geometry.Point([139.493, -20.725]).buffer(50000); // 50km buffer
  const townsville = ee.Geometry.Point([146.817, -19.259]).buffer(50000); // 50km buffer

  // Date range: January 27 to February 10, 2019
  const startDate = '2019-01-27';
  const endDate = '2019-02-11'; // Exclusive end date

  // Load GPM precipitation data
  const precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .select('precipitationCal');

  // Check if collection is empty
  const colSize = precipCol.size().getInfo();
  if (colSize === 0) {
    print("No precipitation data found for the date range.");
    print("<answer>C1</answer>");
    return;
  }

  // Sum precipitation over the period
  const totalPrecip = precipCol.sum();

  // Function to calculate stats for a region
  function getRegionStats(region, name) {
    const stats = totalPrecip.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
      geometry: region,
      scale: 10000,
      maxPixels: 1e9
    });

    const mean = stats.get('precipitationCal_mean').getInfo();
    const count = stats.get('precipitationCal_count').getInfo();

    print(`${name}: Mean rainfall: ${mean !== null ? mean.toFixed(1) : 'null'} mm, Valid pixels: ${count}`);
    return {mean, count};
  }

  // Get stats for both regions
  const mountIsaStats = getRegionStats(mountIsa, 'Mount Isa');
  const townsvilleStats = getRegionStats(townsville, 'Townsville');

  // Check for no valid pixels
  if (mountIsaStats.count === 0 || townsvilleStats.count === 0) {
    print("No valid pixels in one or both regions.");
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (mountIsaStats.mean === null || townsvilleStats.mean === null || 
      isNaN(mountIsaStats.mean) || isNaN(townsvilleStats.mean)) {
    print("Invalid precipitation values detected.");
    print("<answer>C3</answer>");
    return;
  }

  // Check if rainfall exceeds 650 mm (65 cm)
  const mountIsaOver65cm = mountIsaStats.mean > 650;
  const townsvilleOver65cm = townsvilleStats.mean > 650;

  print(`Images in period: ${colSize}`);
  print(`Mount Isa >65cm: ${mountIsaOver65cm}`);
  print(`Townsville >65cm: ${townsvilleOver65cm}`);

  // Both regions need to exceed 65cm for "Yes" answer
  if (mountIsaOver65cm && townsvilleOver65cm) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
